from h34 import *
M=mcq;F=tf;S=short;N=num
b='<text x="10" y="22" font-weight="bold">Th H T O place value: 3452</text>'
for i,(h,v,c) in enumerate([('Th','3000','#c0392b'),('H','400','#e67e22'),('T','50','#2e86c1'),('O','2','#27ae60')]):
    x=30+i*140
    b+=f'<rect x="{x}" y="40" width="120" height="40" fill="{c}" opacity="0.85"/><text x="{x+60}" y="67" text-anchor="middle" fill="#fff" font-size="20">{h}</text>'
    b+=f'<rect x="{x}" y="80" width="120" height="44" fill="#fff" stroke="{c}" stroke-width="2"/><text x="{x+60}" y="110" text-anchor="middle" font-size="22">{["3","4","5","2"][i]}</text>'
    b+=f'<text x="{x+60}" y="150" text-anchor="middle" font-size="16">{v}</text>'
b+='<text x="30" y="185" font-size="16">3452 = 3000 + 400 + 50 + 2 (three thousand four hundred fifty two)</text>'
svgfile('c4-maths-thousands-place-value.svg',620,200,b)
chapter(4,'maths','thousands-around-us','Thousands Around Us',
 ('The langar at the Gurudwara','Jaspreet and Gulnaz are helping to organise a langar, a community lunch, in their neighbourhood Gurudwara. They expect about one thousand people to be fed, and fifty-five volunteers will serve. In this chapter you will learn how to write, read, compare and order numbers from 1000 to 9999 using the Indian place value system.'),
 [('Numbers up to 999 revised',['Many donations arrive for the langar, and Jaspreet and Gulnaz write each donation as a number. A number can be shown with ones, tens and hundreds, for example 4 ones and 7 tens make 74.','Numbers can also be written as a subtraction. 100 minus 7 is 93, because it is 7 less than one hundred.','Ten more than three hundred twelve is 322. When we add a ten, only the tens digit goes up by one.','Jaspreet and Gulnaz count the people who come at different times and draw them with HTO blocks. 52 people are 5 tens and 2 ones; 145 people are 1 hundred, 4 tens and 5 ones; 325 people are 3 hundreds, 2 tens and 5 ones; 508 people are 5 hundreds, 0 tens and 8 ones.','The time slot with the biggest number is the one when the most people came, and the smallest number is the least. Here 508 is the most and 52 is the least.']),
  ('Making and ordering 3-digit numbers',['With the digits 3 and 7 you can make 333, 337, 373, 377, 733, 737, 773 and 777. Digits can repeat. The smallest is 333 and the largest is 777.','If the digits are 3, 5, 0 and 8 and the number must be less than 550, the hundreds digit has to be 3 or 5, and if it is 5 then the tens digit must be 0, 3 or 5 or less than 5 and so on. For example 308, 350, 503, 538, 380 and 505 are all less than 550.','On a number line from 200 to 600, we put each number where it belongs: 308 is a little after 300, and 538 is close to 550.','When a sequence goes up by 1, the ones digit changes: 787, 788. When it goes up by 10, the tens digit changes: 679, 689. We use this to fill in blanks.']),
  ('Crossing 999: the number 1000',['After 999 comes 1000. Gulnaz and Jaspreet keep a number chart and when the chart reaches 1000, the thousandth person has come for the langar.','Ten hundreds make one thousand. So 10 ones make a ten, 10 tens make a hundred and 10 hundreds make a thousand.','The numbers after 1000 are 1001, 1002, 1003 and so on. Look at them carefully: 1001 is one thousand and one.','The Indian system uses only ten symbols, 0 to 9, to write every number, however big. This system was discovered in India about 2000 years ago and is now used all over the world.']),
  ('How many? Choosing the right range',['Some things you count are small in number and some are very large. The number of children in your village is more than 1000, but the number of fingers on your hand is only 5.','The number of teachers in your school may be between 10 and 50, and the number of tables in your classroom may be between 10 and 50. The number of books in the school library is in hundreds, and the number of leaves on a tree is more than 1000.','Think about each situation and decide which range of numbers fits best. Different children may give different answers, and that is fine if they can explain their thinking.']),
  ('Thousands, hundreds, tens and ones',['A 4-digit number has four places: Thousands (Th), Hundreds (H), Tens (T) and Ones (O). We read it starting from the thousands.','The value of a digit depends on its place. In 3452, the 3 is in the thousands place and stands for 3000, the 4 stands for 400, the 5 stands for 50 and the 2 stands for 2.','The expanded form of 3452 is 3000 + 400 + 50 + 2. In words we say three thousand four hundred fifty two.','Take 4085. It is 4000 + 80 + 5. The hundreds digit is 0, so we write the 0 to keep the other digits in their places. Zero is a place holder. In words, 4085 is four thousand eighty five.','Arrow cards of 1000s, 100s, 10s and 1s help us make numbers. We pick the thousand card, the hundred card, the ten card and the one card, and put them together so that the arrow heads match.']),
  ('Making and changing numbers with tokens',['Use tokens of 1s, 10s, 100s and 1000s. 6 tens and 22 ones: 60 + 22 = 82. 4 tens and 12 ones: 40 + 12 = 52.','3 hundreds, 14 tens and 8 ones is 300 + 140 + 8 = 448. 12 hundreds, 18 tens and 2 ones is 1200 + 180 + 2 = 1382.','1 thousand, 5 hundreds, 10 tens and 17 ones is 1000 + 500 + 100 + 17 = 1617. When many ones or tens collect, we regroup them to make the next bigger place.','On a place value slider, 1895 increased by 1 is 1896 and increased by 10 is 1905. 3369 decreased by 2 is 3367 and 5648 decreased by 10 is 5638. 6487 increased by 20 is 6507.','Be careful when you write the number from words. 7 Thousand 0 Hundreds 2 Tens 4 Ones is 7024, not 724, because the 0 hundreds must be shown. 5 Thousand 6 Hundreds 0 Tens 3 Ones is 5603, not 563.']),
  ('Number lines',['On a number line, numbers that are close are placed close together. Between 2226 and 3226 lie 2300, 2900 and 3000, but not 2100 or 3300.','If 1001 and 1038 are marked, then 1043 is a little to the right of 1038, 1069 is further, and 1084 is more to the right still. We go in order from smaller to bigger.','Numbers like 2025, 2080, 2175, 2245 and 2295 all lie between 2000 and 2300. We can mark them as being in the first, second or third part of that stretch.']),
  ('Comparing numbers',['To compare two numbers, we first look at the digit with the biggest place value, which is the thousands digit. The number with the bigger thousands digit is the bigger number.','If the thousands digits are the same, we look at the hundreds digits, then the tens digits and then the ones.','Why is 3102 bigger than 3012? Both have 3 thousands. 3102 has 1 hundred and 3012 has 0 hundreds, so 3102 is bigger.','We use the sign < for smaller than and > for greater than. 1213 < 2121, and 2190 < 2910. We write 1009 < 9001, and 982 < 1024 because a 4-digit number is always bigger than a 3-digit number.','To order numbers, compare them in pairs. Increasing order goes from the smallest to the biggest. Decreasing order goes from the biggest to the smallest.','Prices 1986, 1099 and 1899 in increasing order are 1099 < 1899 < 1986. The runs of five women cricketers in increasing order are 4064, 4814, 5114, 6002, 7805.','The mountain heights in decreasing order are K2 8611, Kangchenjunga 8586, Nanda Devi 7816, Chaukhamba I 7138, Mullayanagiri 1930, Kalsubai 1646 and Bailadila 1276.','Be careful when you compare expressions. 2 tens + 4 thousands + 3 hundreds is 4320, so it is greater than 2043 and equal to 4320. 2 thousands + 9 hundreds + 9 tens + 9 ones is 2999, which is less than 3000.'])],
 [('Write 4085 in expanded form and in words.',[('The digits are 4 thousands, 0 hundreds, 8 tens and 5 ones.','Read each place from the left.'),('4085 = 4000 + 0 + 80 + 5, which is 4000 + 80 + 5.','The 0 hundreds adds nothing but keeps the places right.'),('In words: four thousand eighty five.','Do not say hundred because there are no hundreds.')]),
  ('Compare 3102 and 3012.',[('Compare the thousands digits: 3 and 3 are the same.','Same, so look at the next place.'),('Compare the hundreds digits: 1 and 0. 1 is bigger.','This decides.'),('So 3102 > 3012.','The number with more hundreds is bigger.')]),
  ('Which number is made by 12 hundreds, 18 tens and 2 ones?',[('12 hundreds = 1200.','12 × 100.'),('18 tens = 180.','18 × 10.'),('1200 + 180 + 2 = 1382.','Add them all.')]),
  ('Arrange 4814, 4064, 7805 and 5114 in increasing order.',[('Look at thousands digits: 4, 4, 7, 5. 7 is the biggest and the two 4s are the smallest.','Compare the biggest place first.'),('Between 4814 and 4064, 4814 has 8 hundreds and 4064 has 0 hundreds, so 4064 is smaller.','Tie, so look at hundreds.'),('Order: 4064, 4814, 5114, 7805.','Smallest to biggest.')])],
 ('Explain how to read and write a 4-digit number, and how to compare two 4-digit numbers.',['Four places: thousands, hundreds, tens and ones','Zero keeps the place','Compare from the thousands place first','Use < and >'],['The number with more digits is smaller','You can compare the ones first']),
 ['Ten hundreds make one thousand; the next number after 999 is 1000.','A 4-digit number has thousands, hundreds, tens and ones places.','Expanded form: 3452 = 3000 + 400 + 50 + 2.','The digit 0 is a place holder, as in 4085.','Compare numbers starting from the thousands place, then hundreds, tens and ones.'],
 [M('1',1,'How many hundreds make one thousand?','10',[('100','100 hundreds make ten thousand'),('1','One hundred is only a tenth of a thousand')],'10 hundreds = 1000.'),
  M('2',1,'Which number comes just after 999?','1000',[('9999','That is a much bigger number'),('990','That is smaller than 999')],'After 999 comes 1000.'),
  M('3',1,'What is the expanded form of 3452?','3000 + 400 + 50 + 2',[('300 + 40 + 5 + 2','That is 342.. numbers of a different size'),('3000 + 40 + 500 + 2','The digits are in the wrong places')],'Each digit takes the value of its place.'),
  F('4',1,'The digit 0 in 4085 is a place holder.',True,'It shows there are no hundreds and keeps 4 in the thousands place.'),
  M('5',2,'7 Thousand 0 Hundreds 2 Tens 4 Ones is written as ___.','7024',[('724','You left out the 0 hundreds'),('7240','The digits moved to wrong places')],'Thousands 7, hundreds 0, tens 2, ones 4.'),
  M('6',2,'Which sign makes 3102 ? 3012 true?','>',[('<','3102 has more hundreds'),('=','They are different numbers')],'1 hundred is more than 0 hundreds.'),
  N('7',2,'12 hundreds, 18 tens and 2 ones make which number?',1382,'1200 + 180 + 2 = 1382.',[(1282,'18 tens is 180, not 80'),(3000,'You added 12 + 18 + 2 wrongly')]),
  M('8',2,'Which is the smallest of 4064, 4814, 5114 and 7805?','4064',[('4814','4064 has fewer hundreds'),('7805','It has the most thousands')],'Both 4064 and 4814 have 4 thousands, and 0 hundreds is less than 8.'),
  M('9',2,'5000 + 30 + 4 = ___','5034',[('5340','That is 5000 + 300 + 40'),('534','You left out a zero')],'There are 0 hundreds, 3 tens and 4 ones.'),
  N('10',3,'1895 increased by 10 gives which number?',1905,'The tens digit 9 becomes 10, so we carry one to the hundreds: 1895 + 10 = 1905.',[(1896,'That is adding 1'),(1805,'You forgot the carry to hundreds')]),
  M('11',3,'Which mountain range is the highest in the list: K2 8611, Kangchenjunga 8586, Nanda Devi 7816?','K2',[('Kangchenjunga','8611 is more than 8586'),('Nanda Devi','7816 is smaller than both')],'Compare thousands then hundreds: 8611 is the biggest.'),
  F('12',3,'982 is greater than 1024.',False,'A 3-digit number is always smaller than a 4-digit number. 982 < 1024.')],
 svgs=[('c4-maths-thousands-place-value','Four boxes for Th, H, T and O hold the digits 3, 4, 5 and 2 with values 3000, 400, 50 and 2.','Each digit has a value according to its place.')],
 keep=['thousand','hundred','place value'])
